def valid_snapshot(policy: boundaries.Policy) -> boundaries.Snapshot:
    edges = policy.canonical_edges | policy.migration_edges
    dependencies = {name: set() for name in policy.packages}
    normal_dependencies = {name: set() for name in policy.packages}
    for edge in edges:
        dependencies[edge.dependent].add(edge.dependency)
        if edge not in policy.dev_only_edges:
            normal_dependencies[edge.dependent].add(edge.dependency)
    dependencies["litchi-core"].update(item.name for item in policy.core_dependency_debt)
    normal_dependencies["litchi-core"].update(
        item.name for item in policy.core_dependency_debt
    )
    frozen_dependencies = {
        name: frozenset(items) for name, items in dependencies.items()
    }
    frozen_normal_dependencies = {
        name: frozenset(items) for name, items in normal_dependencies.items()
    }
    features = {name: frozenset() for name in policy.packages}
    features["litchi-core"] = frozenset(item.name for item in policy.core_feature_debt)
    facade_optional_dependencies = frozenset(
        edge.dependency
        for edge in edges
        if edge.dependent == "litchi" and edge.dependency != "litchi-core"
    )
    return boundaries.Snapshot(
        packages=policy.packages,
        manifests=frozenset(),
        edges={
            edge: (
                f"kind={'dev' if edge in policy.dev_only_edges else 'normal'}, "
                "optional=false, target=*, rename=-",
            )
            for edge in edges
        },
        dependency_kinds={
            edge: frozenset({"dev" if edge in policy.dev_only_edges else "normal"})
            for edge in edges
        },
        dependencies=frozen_dependencies,
        normal_dependencies=frozen_normal_dependencies,
        features=features,
        feature_definitions={
            "litchi": {
                "default": frozenset(),
                "all": frozenset(
                    f"dep:{dependency}" for dependency in facade_optional_dependencies
                ),
            }
        },
        normal_optional_dependencies={"litchi": facade_optional_dependencies},
    )


def write_cargo_manifest_fixture(root: Path, relative: str, source: str) -> Path:
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8")
    return path


def add_iwa_numbers_model_storage_scaffold(
    root: Path,
    *,
    permissive_owner_probe: bool = False,
    direct_storage_parse: bool = False,
    permissive_attached_role: bool = False,
) -> None:
    """Create the strict Numbers model/storage lookup fixture.

    The fixture deliberately keeps generated decoding outside the owner probe:
    ``decode_table_info`` may materialize the one admitted payload, while
    ``find_table_owner`` only consumes the explicit candidate projection.
    """

    model = root / boundaries.IWA_NUMBERS_MODEL_SOURCE
    model.parent.mkdir(parents=True, exist_ok=True)
    owner_probe = (
        "        let _ = tst::TableInfoArchive::decode(message.data.as_slice());\n"
        if permissive_owner_probe
        else ""
    )
    attached_role_probe = (
        "    let _ = tst::TableInfoArchive::decode(message.data.as_slice());\n"
        if permissive_attached_role
        else ""
    )
    model.write_text(
        "fn table_info_message_index(object: &ArchiveObject) {\n"
        "    let _ = TABLE_INFO_MESSAGE_TYPES;\n"
        "    let _ = table_info_model_identifier;\n"
        "    let _ = object;\n"
        "}\n"
        "fn decode_table_info(object: &ArchiveObject) {\n"
        "    let _ = table_info_message_index(object);\n"
        "    let _ = object.messages[index].data;\n"
        "    let _ = tst::TableInfoArchive::decode(object.messages[index].data);\n"
        "}\n"
        "fn find_table_owner(package: &IWorkPackage) {\n"
        "    package.with_parsed_archive(name, |archive| {\n"
        "        let _ = table_info_message_index(archive);\n"
        f"{owner_probe}"
        "    });\n"
        "}\n"
        "fn attached_table_info_model_identifier(message: &RawMessage) {\n"
        "    let _ = TABLE_INFO_MESSAGE_TYPES;\n"
        "    let table_info_id = table_info_model_identifier(message);\n"
        "    if message.type_ != TABLE_INFO_MESSAGE_TYPES[0] { return; }\n"
        "    let is_table_model = matches!(\n"
        "        probe_candidate(message.type_, message.data.as_slice()),\n"
        "        CandidateProbe::Valid,\n"
        "    );\n"
        f"{attached_role_probe}"
        "    match (table_info_id, is_table_model) {\n"
        "        (Some(_), true) => panic!(\"ambiguous type-6000\"),\n"
        "        _ => {}\n"
        "    }\n"
        "}\n"
        "fn attached_table_descriptor(package: &IWorkPackage) {\n"
        "    attached_table_info_model_identifier(message);\n"
        "    let _ = package;\n"
        "}\n"
        "fn attached_table_descriptors(package: &IWorkPackage) {\n"
        "    attached_table_info_model_identifier(message);\n"
        "    let _ = package;\n"
        "}\n",
        encoding="utf-8",
    )

    storage = root / boundaries.IWA_NUMBERS_STORAGE_SOURCE
    storage.parent.mkdir(parents=True, exist_ok=True)
    direct_parse = "    let _ = package.archive(name);\n" if direct_storage_parse else ""
    storage.write_text(
        "fn table_models(package: &IWorkPackage) {\n"
        "    package.with_parsed_archive(name, |archive| { let _ = archive; });\n"
        f"{direct_parse}"
        "}\n"
        "fn object_locations(package: &IWorkPackage) {\n"
        "    package.with_parsed_archive(name, |archive| { let _ = archive; });\n"
        "}\n",
        encoding="utf-8",
    )


def add_iwa_numbers_table_info_projection_scaffold(
    root: Path,
    *,
    projection_generated_decode: bool = False,
    role_projection_call: bool = True,
    table_template_projection_call: bool = True,
    table_template_generated_decode: bool = False,
) -> None:
    """Create the migrated Numbers TableInfo discovery source topology.

    The fixture keeps complete generated decoding in ``decode_table_info`` to
    prove the ratchet follows only the read-only ownership/template paths.
    Those two paths use the private typed projection and its bounded Buffa
    codec; the storage cache fixture remains covered by the older audit.
    """

    add_iwa_numbers_model_storage_scaffold(root)

    editor = root / boundaries.IWA_NUMBERS_EDITOR_MODULE_SOURCE
    editor.parent.mkdir(parents=True, exist_ok=True)
    editor.write_text(
        "mod table_info_projection;\n",
        encoding="utf-8",
    )

    projection = root / boundaries.IWA_NUMBERS_TABLE_INFO_PROJECTION_SOURCE
    projection.parent.mkdir(parents=True, exist_ok=True)
    generated = (
        "fn legacy_probe(source: &[u8]) {\n"
        "    let _ = tst::TableInfoArchive::decode(source);\n"
        "}\n"
        if projection_generated_decode
        else ""
    )
    projection.write_text(
        "use std::num::NonZeroU64;\n"
        "use litchi_iwa_common::{WireLimits, LimitKind};\n"
        "use litchi_iwa_protos::table_info_codec;\n"
        "fn model_reference(source: &[u8]) -> Result<NonZeroU64> {\n"
        "    table_info_codec::decode_table_model_reference(\n"
        "        source, table_info_codec::DecodeOptions::new(\n"
        "            source.len(), WireLimits::MAX_FIELDS, WireLimits::MAX_REWRITE_WORK, 64\n"
        "        )\n"
        "    )\n"
        "}\n"
        "fn model_reference_for_type(message_type: u32, source: &[u8]) -> Result<NonZeroU64> {\n"
        "    let _ = message_type;\n"
        "    model_reference(source)\n"
        "}\n"
        f"{generated}",
        encoding="utf-8",
    )

    model = root / boundaries.IWA_NUMBERS_MODEL_SOURCE
    model.write_text(
        "fn table_info_message_index(object: &ArchiveObject) {\n"
        "    let _ = TABLE_INFO_MESSAGE_TYPES;\n"
        "    let _ = table_info_model_identifier(message);\n"
        "    let _ = object;\n"
        "}\n"
        "fn decode_table_info(object: &ArchiveObject) {\n"
        "    let _ = table_info_message_index(object);\n"
        "    let _ = object.messages[index].data;\n"
        "    let _ = tst::TableInfoArchive::decode(object.messages[index].data);\n"
        "}\n"
        "fn find_table_owner(package: &IWorkPackage) {\n"
        "    package.with_parsed_archive(name, |archive| {\n"
        "        let _ = table_info_message_index(archive);\n"
        "    });\n"
        "}\n"
        "fn attached_table_info_model_identifier(object: &ArchiveObject, message: &RawMessage) {\n"
        "    let _ = TABLE_INFO_MESSAGE_TYPES;\n"
        "    let table_info_id = "
        + (
            "super::table_info_projection::model_reference_for_type(message.type_, message.data)"
            if role_projection_call
            else "table_info_model_identifier(message)"
        )
        + ";\n"
        "    if message.type_ != TABLE_INFO_MESSAGE_TYPES[0] { return; }\n"
        "    let is_table_model = matches!(\n"
        "        probe_candidate(message.type_, message.data.as_slice()),\n"
        "        CandidateProbe::Valid,\n"
        "    );\n"
        "    if matches!(table_info_id, Some(_)) && is_table_model {\n"
        "        return Err(ambiguous_role());\n"
        "    }\n"
        "    let _ = object;\n"
        "}\n"
        "fn attached_table_descriptor(package: &IWorkPackage) {\n"
        "    attached_table_info_model_identifier(object, message);\n"
        "    let _ = package;\n"
        "}\n"
        "fn attached_table_descriptors(package: &IWorkPackage) {\n"
        "    attached_table_info_model_identifier(object, message);\n"
        "    let _ = package;\n"
        "}\n",
        encoding="utf-8",
    )

    table_create = root / boundaries.IWA_NUMBERS_TABLE_CREATE_SOURCE
    table_create.parent.mkdir(parents=True, exist_ok=True)
    template_decode = (
        "    let _ = tst::TableInfoArchive::decode(message.data);\n"
        if table_template_generated_decode
        else ""
    )
    template_call = (
        "    model::attached_table_info_model_identifier(info_object, message);\n"
        if table_template_projection_call
        else "    let _ = message;\n"
    )
    table_create.write_text(
        "fn attached_table_templates(package: &IWorkPackage) {\n"
        f"{template_call}"
        f"{template_decode}"
        "    let _ = package;\n"
        "}\n",
        encoding="utf-8",
    )


def add_iwa_shared_media_playback_scaffold(
    root: Path,
    *,
    restore_shared_host: bool = False,
    owner_generated_decode: bool = False,
    host_generated_decode: bool = False,
) -> None:
    """Create the three focused playback owners and their thin host adapters."""

    codec = root / boundaries.IWA_MEDIA_PLAYBACK_CODEC_SOURCE
    codec.parent.mkdir(parents=True, exist_ok=True)
    codec.write_text(
        "fn decode_movie_playback() {}\n"
        "fn rewrite_movie_playback() {}\n",
        encoding="utf-8",
    )

    owner_sources = {
        "Keynote": (
            "pub fn __decode_movie_playback_payload(source: &[u8], limits: WireLimits) "
            "{ movie_playback_codec::decode_movie_playback_with_report(source, limits); }\n"
        ),
        "Pages": (
            "pub fn __decode_movie_playback_payload(source: &[u8], limits: WireLimits) "
            "{ movie_playback_codec::decode_movie_playback(source, limits); }\n"
            "#[doc(hidden)]\n"
            "pub fn __rewrite_movie_playback_payload(source: &[u8], settings: MediaPlaybackSettings, limits: WireLimits) "
            "{ movie_playback_codec::rewrite_movie_playback(source, settings, limits); }\n"
        ),
        "Numbers": (
            "pub fn __movie_playback_settings(source: &[u8], limits: WireLimits) "
            "{ movie_playback_codec::decode_movie_playback(source, limits); }\n"
            "#[doc(hidden)]\n"
            "pub fn __rewrite_movie_playback_settings(source: &[u8], settings: MediaPlaybackSettings, limits: WireLimits) "
            "{ movie_playback_codec::rewrite_movie_playback(source, settings, limits); }\n"
        ),
    }
    for ecosystem, relative in boundaries.IWA_MEDIA_PLAYBACK_OWNER_SOURCES.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        decode_name, rewrite_name = boundaries.IWA_MEDIA_PLAYBACK_OWNER_SEAMS[ecosystem]
        source = owner_sources[ecosystem]
        source = (
            "#[doc(hidden)]\n" + source
            if not source.startswith("#[doc(hidden)]")
            else source
        )
        if owner_generated_decode and ecosystem == "Pages":
            source += "fn legacy() { tsd::MovieArchive::decode(source); }\n"
        path.write_text(source, encoding="utf-8")

        package = root / boundaries.IWA_MEDIA_PLAYBACK_OWNER_PACKAGE_SOURCES[ecosystem]
        package.parent.mkdir(parents=True, exist_ok=True)
        module = (
            "mod slide_movie_playback;\n"
            if ecosystem == "Keynote"
            else "#[cfg(feature = \"internal-iwork-source\")]\nmod movie_playback;\n"
        )
        reexports = ", ".join(
            name for name in (decode_name, rewrite_name) if name is not None
        )
        package.write_text(
            module
            + "#[cfg(feature = \"internal-iwork-source\")]\n"
            + "#[doc(hidden)]\n"
            + f"pub use {'slide_movie_playback' if ecosystem == 'Keynote' else 'movie_playback'}::{{{reexports}}};\n",
            encoding="utf-8",
        )
        export = root / boundaries.IWA_MEDIA_PLAYBACK_OWNER_EXPORT_SOURCES[ecosystem]
        export.parent.mkdir(parents=True, exist_ok=True)
        export.write_text(
            "#[cfg(feature = \"internal-iwork-source\")]\n"
            "#[doc(hidden)]\n"
            + f"pub use package::{{{reexports}}};\n",
            encoding="utf-8",
        )

    hosts = {
        "Keynote": {
            boundaries.IWA_MEDIA_PLAYBACK_HOST_SOURCES["Keynote"][0]:
                "fn movie_info() { litchi_keynote::__decode_movie_playback_payload(source, limits); }\n",
            boundaries.IWA_MEDIA_PLAYBACK_HOST_SOURCES["Keynote"][1]:
                "fn audio_info() { litchi_keynote::__decode_movie_playback_payload(source, limits); }\n",
        },
        "Pages": {
            boundaries.IWA_MEDIA_PLAYBACK_HOST_SOURCES["Pages"][0]:
                "fn movie_playback_settings() { litchi_pages::__decode_movie_playback_payload(source, limits); }\n"
                "fn replace_movie_playback_settings() { litchi_pages::__rewrite_movie_playback_payload(source, settings, limits); }\n",
        },
        "Numbers": {
            boundaries.IWA_MEDIA_PLAYBACK_HOST_SOURCES["Numbers"][0]:
                "fn movie_playback_settings_from_payload() { litchi_numbers::__movie_playback_settings(source, limits); }\n"
                "fn replace_movie_playback_settings() { litchi_numbers::__rewrite_movie_playback_settings(source, settings, limits); }\n",
        },
    }
    for ecosystem, entries in hosts.items():
        for relative, source in entries.items():
            path = root / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            if host_generated_decode and ecosystem == "Numbers":
                source = source.replace(
                    "litchi_numbers::__rewrite_movie_playback_settings(source, settings, limits);",
                    "litchi_numbers::__rewrite_movie_playback_settings(source, settings, limits); "
                    "tsd::MovieArchive::decode(source);",
                )
            path.write_text(source, encoding="utf-8")

    if restore_shared_host:
        shared = root / boundaries.IWA_SHARED_MEDIA_PLAYBACK_SOURCE
        shared.parent.mkdir(parents=True, exist_ok=True)
        shared.write_text("fn media_playback_settings() {}\n", encoding="utf-8")
        root_lib = root / boundaries.IWA_FACADE_SOURCE
        root_lib.parent.mkdir(parents=True, exist_ok=True)
        root_lib.write_text("pub(crate) mod media_playback;\n", encoding="utf-8")


def add_iwa_shared_image_adjustments_scaffold(
    root: Path,
    *,
    restore_shared_host: bool = False,
    owner_generated_decode: bool = False,
    codec_generated_decode: bool = False,
    host_legacy_helper: bool = False,
    missing_hidden_gate: bool = False,
    semantic_module_gate: bool = False,
) -> None:
    """Create the focused image-adjustment owners and thin host ingress."""

    codec = root / boundaries.IWA_IMAGE_ADJUSTMENTS_CODEC_SOURCE
    codec.parent.mkdir(parents=True, exist_ok=True)
    codec.write_text(
        "use buffa::DecodeOptions as BuffaDecodeOptions;\n"
        "struct ImageAdjustmentsSnapshot;\n"
        "struct ImageAdjustmentsWrite;\n"
        "struct DecodeOptions;\n"
        "fn decode_image_adjustments(source: &[u8], options: DecodeOptions) -> ImageAdjustmentsSnapshot {\n"
        "    let _ = buffa::decode_view(source, options);\n"
        "    ImageAdjustmentsSnapshot\n"
        "}\n"
        "fn rewrite_image_adjustments(source: &[u8], write: ImageAdjustmentsWrite, options: DecodeOptions) -> Vec<u8> {\n"
        "    let _ = (source, write, options);\n"
        "    Vec::new()\n"
        "}\n",
        encoding="utf-8",
    )
    codec_public = root / boundaries.IWA_IMAGE_ADJUSTMENTS_CODEC_PUBLIC_SOURCE
    codec_public.parent.mkdir(parents=True, exist_ok=True)
    codec_public.write_text(
        "#[doc(hidden)]\n"
        "pub mod image_adjustments_codec;\n",
        encoding="utf-8",
    )
    if codec_generated_decode:
        codec.write_text(
            codec.read_text(encoding="utf-8")
            + "fn legacy(source: &[u8]) { tsd::ImageArchive::decode(source); }\n",
            encoding="utf-8",
        )

    for ecosystem, relative in boundaries.IWA_IMAGE_ADJUSTMENTS_OWNER_SOURCES.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        read_method, edit_method, apply_method = (
            boundaries.IWA_IMAGE_ADJUSTMENTS_SEMANTIC_METHODS[ecosystem]
        )
        selectors = boundaries.IWA_IMAGE_ADJUSTMENTS_SEMANTIC_SELECTORS[ecosystem]
        selector_arguments = ", ".join(
            f"{selector.lower()}_selector: {selector}" for selector in selectors
        )
        selector_names = ", ".join(
            f"{selector.lower()}_selector" for selector in selectors
        )
        semantic_types = boundaries.IWA_IMAGE_ADJUSTMENTS_SEMANTIC_TYPES[ecosystem]
        semantic_error = semantic_types[0]
        rewrite_bridge = ""
        if (
            boundaries.IWA_IMAGE_ADJUSTMENTS_RETIRED_WRITE_SEAM
            in boundaries.IWA_IMAGE_ADJUSTMENTS_OWNER_SEAMS_BY_ECOSYSTEM[ecosystem]
        ):
            rewrite_bridge = (
                '#[cfg(feature = "internal-iwork-source")]\n'
                "#[doc(hidden)]\n"
                "pub fn __rewrite_image_adjustments_payload(source: &[u8], adjustments: ImageAdjustments, limits: WireLimits) "
                "-> Result<Vec<u8>, ImageAdjustmentsError> {\n"
                "    let _ = (adjustments, limits);\n"
                "    codec::rewrite_image_adjustments(source, write, limits)\n"
                "}\n"
            )
        source = (
            f"pub enum {semantic_error} {{ Error }}\n"
            f"pub struct {semantic_types[1]}<'a> {{ source: &'a Package }}\n"
            f"pub struct {semantic_types[2]} {{}}\n"
            f"pub struct {semantic_types[3]} {{}}\n"
            f"pub struct {semantic_types[4]} {{}}\n"
            f"impl Package {{\n"
            f"    pub fn {read_method}(&self, {selector_arguments}) "
            f"-> Result<ImageAdjustments, {semantic_error}> {{ let _ = ({selector_names}); unimplemented!() }}\n"
            f"    pub fn {edit_method}(&self, {selector_arguments}) "
            f"-> Result<{semantic_types[1]}<'_>, {semantic_error}> {{ let _ = ({selector_names}); unimplemented!() }}\n"
            f"    pub fn {apply_method}(&self, patch: &{semantic_types[3]}) "
            f"-> Result<{semantic_types[2]}, {semantic_error}> {{ let _ = patch; unimplemented!() }}\n"
            "}\n"
            "pub struct Package;\n"
            "pub struct ImageSelector;\n"
            "pub struct SheetSelector;\n"
            "#[cfg(feature = \"internal-iwork-source\")]\n"
            "#[doc(hidden)]\n"
            "pub enum ImageAdjustmentsError { Error }\n"
            "#[cfg(feature = \"internal-iwork-source\")]\n"
            "#[doc(hidden)]\n"
            "pub fn __decode_image_adjustments_payload(source: &[u8], limits: WireLimits) "
            "-> Result<ImageAdjustments, ImageAdjustmentsError> {\n"
            "    let _ = ImageAdjustment::new(0.0);\n"
            "    let _ = codec::DecodeOptions::new(source, limits);\n"
            "    codec::decode_image_adjustments(source, limits)\n"
            "}\n"
            + rewrite_bridge
            + "use litchi_iwa_protos::image_adjustments_codec as codec;\n"
            "use litchi_iwa_common::{WireLimits, shape::image::{ImageAdjustment, ImageAdjustments}};\n"
        )
        if missing_hidden_gate:
            source = source.replace(
                '#[cfg(feature = "internal-iwork-source")]\n#[doc(hidden)]\n'
                "pub enum ImageAdjustmentsError",
                "#[doc(hidden)]\n"
                "pub enum ImageAdjustmentsError",
                1,
            )
            source = source.replace(
                '#[cfg(feature = "internal-iwork-source")]\n#[doc(hidden)]\n'
                "pub fn __decode_image_adjustments_payload",
                "#[doc(hidden)]\n"
                "pub fn __decode_image_adjustments_payload",
                1,
            )
            source = source.replace(
                '#[cfg(feature = "internal-iwork-source")]\n#[doc(hidden)]\n'
                "pub fn __rewrite_image_adjustments_payload",
                "#[doc(hidden)]\n"
                "pub fn __rewrite_image_adjustments_payload",
                1,
            )
        if owner_generated_decode and ecosystem == "Pages":
            source += "fn legacy(source: &[u8]) { tsd::ImageAdjustmentsArchive::decode(source); }\n"
        path.write_text(source, encoding="utf-8")

        package = root / boundaries.IWA_IMAGE_ADJUSTMENTS_OWNER_PACKAGE_SOURCES[ecosystem]
        package.parent.mkdir(parents=True, exist_ok=True)
        hidden_bridge_exports = ["__decode_image_adjustments_payload"]
        if (
            boundaries.IWA_IMAGE_ADJUSTMENTS_RETIRED_WRITE_SEAM
            in boundaries.IWA_IMAGE_ADJUSTMENTS_OWNER_SEAMS_BY_ECOSYSTEM[ecosystem]
        ):
            hidden_bridge_exports.append("__rewrite_image_adjustments_payload")
        hidden_bridge_exports.append("ImageAdjustmentsError")
        package.write_text(
            ("#[cfg(feature = \"internal-iwork-source\")]\n" if semantic_module_gate else "")
            + "mod image_adjustments;\n"
            + "pub use image_adjustments::{"
            + ", ".join(semantic_types)
            + "};\n"
            + ("" if missing_hidden_gate else '#[cfg(feature = "internal-iwork-source")]\n')
            + ("" if missing_hidden_gate else "#[doc(hidden)]\n")
            + "pub use image_adjustments::{"
            + ", ".join(hidden_bridge_exports)
            + "};\n",
            encoding="utf-8",
        )
        export = root / boundaries.IWA_IMAGE_ADJUSTMENTS_OWNER_EXPORT_SOURCES[ecosystem]
        export.parent.mkdir(parents=True, exist_ok=True)
        export.write_text(
            "pub use package::{"
            + ", ".join(semantic_types)
            + "};\n"
            + ("" if missing_hidden_gate else '#[cfg(feature = "internal-iwork-source")]\n')
            + ("" if missing_hidden_gate else "#[doc(hidden)]\n")
            + "pub use package::{"
            + ", ".join(hidden_bridge_exports)
            + "};\n",
            encoding="utf-8",
        )

    for ecosystem, relative_root in boundaries.IWA_IMAGE_ADJUSTMENTS_HOST_ROOTS.items():
        path = root / relative_root / "image_adjustments.rs"
        path.parent.mkdir(parents=True, exist_ok=True)
        crate_name = ecosystem.lower()
        source = (
            f"fn read() {{ litchi_{crate_name}::__decode_image_adjustments_payload(source, limits); }}\n"
        )
        if (
            boundaries.IWA_IMAGE_ADJUSTMENTS_RETIRED_WRITE_SEAM
            in boundaries.IWA_IMAGE_ADJUSTMENTS_OWNER_SEAMS_BY_ECOSYSTEM[ecosystem]
        ):
            source += (
                f"fn write() {{ litchi_{crate_name}::__rewrite_image_adjustments_payload(source, adjustments, limits); }}\n"
            )
        if host_legacy_helper and ecosystem == "Pages":
            source += "use crate::image_adjustments::replace_image_adjustments;\n"
        if host_legacy_helper and ecosystem == "Numbers":
            source += "fn legacy() { replace_image_adjustments(source); }\n"
        if host_legacy_helper and ecosystem == "Keynote":
            source += "use super::image_adjustments::image_adjustments_from_archive;\n"
        if host_legacy_helper and ecosystem == "Keynote":
            source += "fn legacy() { image_adjustments_from_archive(source); }\n"
        if host_legacy_helper and ecosystem == "Pages":
            source += "fn legacy() { image_adjustments_from_archive(source); }\n"
        if host_legacy_helper and ecosystem == "Numbers":
            source += "fn legacy() { image_adjustments_from_archive(source); }\n"
        path.write_text(source, encoding="utf-8")

    if restore_shared_host:
        shared = root / boundaries.IWA_SHARED_IMAGE_ADJUSTMENTS_SOURCE
        shared.parent.mkdir(parents=True, exist_ok=True)
        shared.write_text("fn image_adjustments_from_archive() {}\n", encoding="utf-8")
        root_lib = root / boundaries.IWA_FACADE_SOURCE
        root_lib.parent.mkdir(parents=True, exist_ok=True)
        root_lib.write_text("mod image_adjustments;\n", encoding="utf-8")


def add_iwa_keynote_slide_preview_scaffold(
    root: Path,
    *,
    restore_host: bool = False,
    missing_hidden_gate: bool = False,
    host_legacy_route: bool = False,
) -> None:
    """Install the focused Keynote preview owner and one host forwarding route."""

    owner = root / boundaries.KEYNOTE_SLIDE_PREVIEW_OWNER_SOURCE
    owner.parent.mkdir(parents=True, exist_ok=True)
    owner.write_text(
        "use litchi_iwa_common::WireLimits;\n"
        "use litchi_iwa_core::{ArchiveObject, Limits as ArchiveLimits};\n"
        "pub enum InvalidationError { InvalidSource }\n"
        "fn invalidate(object: &mut ArchiveObject, archive_limits: ArchiveLimits, wire_limits: WireLimits) "
        "-> Result<(), InvalidationError> { let _ = (object, archive_limits, wire_limits); Ok(()) }\n"
        + ("" if missing_hidden_gate else '#[cfg(feature = "internal-iwork-source")]\n')
        + "#[doc(hidden)]\n"
        "pub fn __invalidate_slide_preview(object: &mut ArchiveObject, archive_limits: ArchiveLimits, wire_limits: WireLimits) "
        "-> Result<(), InvalidationError> { invalidate(object, archive_limits, wire_limits) }\n",
        encoding="utf-8",
    )

    package = root / (boundaries.KEYNOTE_SOURCE_ROOT / "package.rs")
    package.parent.mkdir(parents=True, exist_ok=True)
    package.write_text(
        "mod slide_preview;\n"
        + ("" if missing_hidden_gate else '#[cfg(feature = "internal-iwork-source")]\n')
        + ("" if missing_hidden_gate else "#[doc(hidden)]\n")
        + "pub use slide_preview::__invalidate_slide_preview;\n",
        encoding="utf-8",
    )
    lib = root / (boundaries.KEYNOTE_SOURCE_ROOT / "lib.rs")
    lib.parent.mkdir(parents=True, exist_ok=True)
    lib.write_text(
        ("" if missing_hidden_gate else '#[cfg(feature = "internal-iwork-source")]\n')
        + ("" if missing_hidden_gate else "#[doc(hidden)]\n")
        + "pub use package::__invalidate_slide_preview;\n",
        encoding="utf-8",
    )

    editor = root / boundaries.IWA_KEYNOTE_EDITOR_SOURCE
    editor.parent.mkdir(parents=True, exist_ok=True)
    editor.write_text(
        ("mod slide_preview;\n" if restore_host else "")
        + "mod slide_layout_update;\n",
        encoding="utf-8",
    )
    layout = root / boundaries.IWA_KEYNOTE_SLIDE_LAYOUT_UPDATE_SOURCE
    layout.parent.mkdir(parents=True, exist_ok=True)
    layout.write_text(
        "fn update(object: &mut ArchiveObject, archive_limits: ArchiveLimits, wire_limits: WireLimits) "
        "-> Result<(), Error> { litchi_keynote::__invalidate_slide_preview(object, archive_limits, wire_limits) }\n",
        encoding="utf-8",
    )
    if restore_host:
        old = root / boundaries.IWA_KEYNOTE_SLIDE_PREVIEW_SOURCE
        old.parent.mkdir(parents=True, exist_ok=True)
        old.write_text(
            "fn invalidate() { kn::SlideNodeArchive::decode(source); }\n",
            encoding="utf-8",
        )
    if host_legacy_route:
        layout.write_text(
            layout.read_text(encoding="utf-8")
            + "fn legacy() { slide_preview::invalidate(object, archive_limits, wire_limits); }\n",
            encoding="utf-8",
        )


