                "[package]\nname = \"consumer\"\nversion = \"0.1\"\n\n"
                "[dependencies]\n"
                "path_alias = { path = \"../litchi-iwa\" }\n\n"
                "[patch.crates-io]\n"
                "patched_iwa = { package = \"litchi-iwa\", path = \"../litchi-iwa\" }\n\n"
