                        "pub(crate) fn restricted(archive: ShowArchive) {}",
                        "struct ShowSettings;",
                        "pub(crate) struct ShowSettingsEdit;",
                        "pub(super) type ShowSettingsPatch = Patch;",
                        "pub(in crate) struct ShowSettingsCommit;",
                        "impl ShowSettingsEdit {}",
