                "pub type TableTitleEdit = Edit;\n"
                "pub fn table_title_settings(object_id: u64, source_bytes: &[u8], "
                "wire: WireView, archive: Archive, generated: GeneratedProjection, "
                "buffa: BuffaView, prost: prost_types::MessageInfo) {}\n",
