    def test_numbers_table_cell_control_bridge_routes_generic_writes_to_owner(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            add_numbers_table_cell_control_canonical_scaffold(root)
            bridge = root / boundaries.IWA_NUMBERS_TABLE_CELL_CONTROL_BRIDGE_SOURCE
            bridge.parent.mkdir(parents=True, exist_ok=True)
            bridge.write_text(
                "use litchi_numbers::cell::CellControl;\n"
                "use litchi_numbers::{Package as FocusedNumbersPackage, SheetSelector, TableSelector};\n"
                "fn focused_cell_location() -> (FocusedNumbersPackage, SheetSelector<'static>, TableSelector<'static>, CellPosition, usize) {\n"
                "    focused_table_location(); CellPosition::try_from_usize(0, 0).unwrap()\n"
                "}\n"
                "fn focused_control_format() {\n"
                "    let (source, sheet, table, position, _) = focused_cell_location();\n"
                "    source.table_cell_control_format(sheet, table, position);\n"
                "}\n"
                "fn focused_set_data_format(source: &FocusedNumbersPackage, sheet: SheetSelector<'static>, table: TableSelector<'static>, position: CellPosition, value: CellControl) {\n"
                "    let commit = source.edit_table_cell_control_format(sheet, table, position).unwrap().set(value).commit();\n"
                "    if commit.patch().is_noop() { return; }\n"
                "}\n"
                "fn focused_clear_data_format(source: &FocusedNumbersPackage, sheet: SheetSelector<'static>, table: TableSelector<'static>, position: CellPosition) {\n"
                "    let commit = source.edit_table_cell_control_format(sheet, table, position).unwrap().clear().commit();\n"
                "    if commit.patch().is_noop() { return; }\n"
                "}\n"
                "fn verify_focused_data_format() {}\n"
                "fn commit_exact_focused_data_format(format: Option<CellControl>) {\n"
                "    let (source, sheet, table, position, _) = focused_cell_location();\n"
                "    match format { Some(value) => focused_set_data_format(&source, sheet, table, position, value), None => focused_clear_data_format(&source, sheet, table, position) };\n"
                "    verify_focused_data_format();\n"
                "}\n"
                "impl NumbersEditor {\n"
                "    pub fn table_cell_data_format(&self) {\n"
                "        if CellControl::try_from(()).is_ok() { focused_control_format(); }\n"
                "    }\n"
                "    pub fn set_table_cell_data_format(&mut self, value: CellControl) {\n"
                "        if uses_focused_data_format_owner() { commit_exact_focused_data_format(Some(value)); return Ok(()); }\n"
                "    }\n"
                "}\n",
                encoding="utf-8",
            )
            self.assertEqual(
                boundaries.audit_iwa_numbers_table_cell_control_bridge_source_topology(
                    root
                ),
                [],
            )

            # Parsed-source extraction may move the staged transaction into a
            # helper. The bridge must still delegate explicitly, and the
            # helper must retain every focused stage and read-back marker.
            delegated = bridge.read_text(encoding="utf-8")
            delegated = delegated.replace(
                "    let (source, sheet, table, position, _) = focused_cell_location();\n"
                "    match format { Some(value) => focused_set_data_format(&source, sheet, table, position, value), None => focused_clear_data_format(&source, sheet, table, position) };\n"
                "    verify_focused_data_format();\n",
                "    commit_exact_focused_data_format_with_location(format);\n",
            )
            delegated = delegated.replace(
                "}\nimpl NumbersEditor {",
                "}\n"
                "fn commit_exact_focused_data_format_with_location(format: Option<CellControl>) {\n"
                "    let (source, sheet, table, position, _) = focused_cell_location();\n"
                "    match format { Some(value) => focused_set_data_format(&source, sheet, table, position, value), None => focused_clear_data_format(&source, sheet, table, position) };\n"
                "    verify_focused_data_format();\n"
                "}\n"
                "impl NumbersEditor {",
            )
            bridge.write_text(delegated, encoding="utf-8")
            self.assertEqual(
                boundaries.audit_iwa_numbers_table_cell_control_bridge_source_topology(
                    root
                ),
                [],
            )
            for marker in (
                "focused_set_data_format",
                "focused_clear_data_format",
                "verify_focused_data_format",
            ):
                with self.subTest(delegated_marker=marker):
                    bridge.write_text(
                        delegated.replace(marker, "removed_focused_stage"),
                        encoding="utf-8",
                    )
                    violations = boundaries.audit_iwa_numbers_table_cell_control_bridge_source_topology(
                        root
                    )
                    self.assertTrue(
                        any(f"dispatch marker {marker}" in item for item in violations),
                        violations,
                    )
            bridge.write_text(delegated, encoding="utf-8")

            broken = bridge.read_text(encoding="utf-8").replace(
                "source.table_cell_control_format(sheet, table, position);",
                "cell_data_format::cell_slider_format();",
            )
            bridge.write_text(broken, encoding="utf-8")
            violations = boundaries.audit_iwa_numbers_table_cell_control_bridge_source_topology(
                root
            )
            self.assertTrue(
                any("must call focused Package table_cell_control_format" in item for item in violations),
                violations,
            )
            self.assertTrue(
                any("legacy per-kind/raw-ID adapter" in item for item in violations),
                violations,
            )

            bridge.write_text(
                broken.replace(
                    "cell_data_format::cell_slider_format();",
                    "source.table_cell_control_format(sheet, table, position);",
                ).replace(
                    "commit_exact_focused_data_format(Some(value));",
                    "cell_data_format::set_cell_data_format();",
                ),
                encoding="utf-8",
            )
            violations = boundaries.audit_iwa_numbers_table_cell_control_source_topology(root)
            self.assertTrue(
                any("retired litchi-iwa Numbers cell-control call" in item for item in violations)
                or any(
                    "generic bridge set_table_cell_data_format must route" in item
                    for item in boundaries.audit_iwa_numbers_table_cell_control_bridge_source_topology(root)
                ),
                violations,
            )

