    def test_numbers_table_cell_fraction_format_codec_rejects_missing_strict_contract(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            add_numbers_table_cell_fraction_format_canonical_scaffold(root)
            codec = root / boundaries.NUMBERS_TABLE_CELL_FRACTION_FORMAT_CODEC_SOURCE
            complete = codec.read_text(encoding="utf-8")
            for marker, expected in (
                ("preflight; ", "strict canonical ingress"),
                ("duplicate; ", "strict canonical ingress"),
                ("unknown; raw; extend_from_slice;", "unknown/raw preservation"),
                ("MAX_RECURSION_LIMIT; ", "bounded prepared rewrite"),
                (
                    "format_type; fraction_accuracy; requires_fraction_replacement;",
                    "fraction format fields",
                ),
                ("format_table; registry; refcount; reference; entry;", "registry/refcount closure"),
            ):
                with self.subTest(marker=marker):
                    missing = complete.replace(marker, "")
                    if expected == "fraction format fields":
                        for field in (
                            "format_type",
                            "FORMAT_TYPE_FIELD",
                            "fraction_accuracy",
                            "FORMAT_FRACTION_ACCURACY_FIELD",
                            "FractionAccuracy",
                            "accuracy",
                            "requires_fraction_replacement",
                        ):
                            missing = missing.replace(field, "")
                    codec.write_text(missing, encoding="utf-8")
                    violations = boundaries.audit_numbers_table_cell_fraction_format_codec_source_topology(
                        root
                    )
                    self.assertTrue(
                        any(
                            f"missing strict {expected} marker" in item
                            for item in violations
                        ),
                        (expected, violations),
                    )

            for marker, expected in (
                (
                    "state.requires_fraction_replacement = Some(value != 0);",
                    "must accept only canonical false",
                ),
                (
                    "if snapshot.requires_fraction_replacement() == Some(true) { return Err; }",
                    "must reject true field-20 replacement markers",
                ),
                (
                    "view.requires_fraction_replacement != snapshot.requires_fraction_replacement;",
                    "must preserve the accepted field-20 false marker",
                ),
            ):
                with self.subTest(marker=marker):
                    codec.write_text(
                        complete.replace(marker, ""),
                        encoding="utf-8",
                    )
                    violations = boundaries.audit_numbers_table_cell_fraction_format_codec_source_topology(
                        root
                    )
                    self.assertTrue(
                        any(expected in item for item in violations),
                        (expected, violations),
                    )

            codec.write_text(
                complete.replace(
                    "pub fn canonical_fraction_format() { format_type; fraction_accuracy; }",
                    "pub fn canonical_fraction_format() { format_type; fraction_accuracy; requires_fraction_replacement; }",
                ),
                encoding="utf-8",
            )
            violations = boundaries.audit_numbers_table_cell_fraction_format_codec_source_topology(
                root
            )
            self.assertTrue(
                any("must not synthesize field-20 replacement markers" in item for item in violations),
                violations,
            )

            codec.write_text(
                complete.replace(
                    "NATIVE_FRACTION_FORMAT_TYPE: u32 = 262",
                    "NATIVE_FRACTION_FORMAT_TYPE: u32 = 256",
                ),
                encoding="utf-8",
            )
            violations = boundaries.audit_numbers_table_cell_fraction_format_codec_source_topology(
                root
            )
            self.assertTrue(any("native type 262" in item for item in violations), violations)

            codec.write_text(
                complete.replace("preflight; let _ =", "let _ ="),
                encoding="utf-8",
            )
            violations = boundaries.audit_numbers_table_cell_fraction_format_codec_source_topology(
                root
            )
            self.assertTrue(any("preflight wire before" in item for item in violations), violations)

            codec.write_text(complete + "use prost::Message;\n", encoding="utf-8")
            violations = boundaries.audit_numbers_table_cell_fraction_format_codec_source_topology(
                root
            )
            self.assertTrue(any("Prost production path" in item for item in violations), violations)

